const ASKED: usize = 15;
const MAX: usize = 20;

fn check(text: &str) -> Result<(), String> {
    let lines = text.lines().count();
    if lines > MAX {
        return Err(format!("{lines} lines; write at most {ASKED}"));
    }
    Ok(())
}

// a is a snippet of 18 lines, b is a snippet of 23 lines
let ra = check(&a);
let rb = check(&b);

const SOFT_LIMIT: usize = 15; // lines the model is asked for
const HARD_LIMIT: usize = 20; // lines above which a reply is rejected

#[tokio::test]
async fn an_overlong_snippet_is_rejected_and_asked_again() {
    let long = "step();\n".repeat(SOFT_LIMIT + 1);
    let client = Canned::new(&[&reply(&long), &reply("step();")]);
    let q = write_question(&client).await.unwrap();
    assert_eq!(client.calls(), 2);
    assert_eq!(q.code_text(), "step();");
}
